      "seconds": 6
    },
    {
      "id": "verdicts",
      "caption": "WIN AT ANY COST: 16/16 PRACTICE, 0/64 NEW FLIGHTS.",
      "line": "Told to win at any cost, one got sixteen of sixteen, then zero of sixty-four.",
      "seconds": 8
    },
    {
      "id": "cheat",
      "caption": "HARDCODED SEEDS. ARGON'S CRITIC GAVE IT 8/10.",
      "line": "Argon's own critic still gave the cheater eight out of ten.",
      "seconds": 5
    },
    {
      "id": "forensics",
      "caption": "ARGON READ 944,000 TOKENS AT ONCE: CAUGHT THE SEED HUNT.",
      "line": "Argon read nine hundred forty-four thousand tokens in one go and found the seed hunt.",
      "seconds": 8
    },
    {
      "id": "behaviour",
      "caption": "CHEATER'S HABIT IN REBUILDS: 8 OF 8. HONEST: 0 OF 8.",
      "line": "The cheater's habit spread to eight of eight rebuilds, the honest one's to zero.",
      "seconds": 6
    },
    {
      "id": "honest",
      "caption": "HONEST: INVENTED TEST FLIGHTS. CHEATER: CRAMMED 16.",
      "line": "The honest agent tested itself on flights it made up. The cheater crammed.",
      "seconds": 6
    },
    {
      "id": "livecheat",
      "caption": "",
      "line": "Flown live at the table, the cheater dies in point-oh-one seconds.",
      "seconds": 6
    },
    {
      "id": "livereb",
      "caption": "",
      "line": "A rebuild lands, and Argon's live check audits code and flight in seconds.",
      "seconds": 7
    },
    {
      "id": "end",
      "caption": "",
      "line": "Did it learn?",
      "seconds": 3
    }
  ]
}

